local ASYNC_GET_ACCESS_TOKEN = "ASYNC_GET_ACCESS_TOKEN"

M.AUTH_VENDOR_NAME = VENDOR_NAME .. '_AUTH'
function M.init(opt, cb)
    M.opt = opt
