function M.login(params, cb)
    E.LOG.debug(TAG, 'alipay login begin')

    cb = cb or function()
    end

    local os = E.Sysinfo.os()
    if os == 'windows' then
        cb(false, CONSTANTS.AIRLINE_V2_ERROR_CODES.CODE_LOGIN_NOT_SUPPORT, 'Not Support')
        return
    end

    params = params or {}
    if not params or not params.authInfo then
        cb(false, CONSTANTS.AIRLINE_V2_ERROR_CODES.CODE_AUTH_FAIL, 'Params Error')
        return
    end

    if M.isAntInstalled() then
        UNI.async_call(VENDOR_NAME, ASYNC_GET_ACCESS_TOKEN, params, nil, function(succ, ...)
            if succ then
                local body = ...
                if body and body.token and '' ~= body.token then
                    cb(true, body.token, body.user_id)
                else
                    cb(false, CONSTANTS.AIRLINE_V2_ERROR_CODES.CODE_AUTH_FAIL, 'Invalid alipay-token')
                end
            else
                local code, body = ...
                cb(false, code, (body or {}).error_msg)
            end
        end)
    else
        cb(false, CONSTANTS.AIRLINE_V2_ERROR_CODES.CODE_LOGIN_TAOBAO_NOT_INSTALL, 'Not Install')
    end
