function M.isAntInstalled()
    local sdk_infos = UNI.get_sdk_infos()
    local os = _ejoysdk.os()
    if sdk_infos and sdk_infos[VENDOR_NAME] then
        local tmp = 'p'..'a'..'y'
        if os == 'android' then
            return E.Sysinfo.is_app_install('com.eg.android.Ali'..tmp..'Gphone')
        else
            if os == 'ios' then
                return E.Sysinfo.is_app_install('ali'..tmp..':')
            end
        end
    end

    return false
end

